type TicketItem={id:number;title:string;status:string;priority:string;requester:string;assignee:string;category:string;updated:string;sla:string;department:string;service?:string;description?:string}
const API_URL=(import.meta.env.VITE_API_URL||'http://localhost:5000/api').replace(/\/$/,'')
async function apiFetch(path:string,options:RequestInit={}){const token=sessionStorage.getItem('novisoft-token');const headers=new Headers(options.headers||{});headers.set('Content-Type','application/json');if(token)headers.set('Authorization',`Bearer ${token}`);const res=await fetch(`${API_URL}${path}`,{...options,headers});if(!res.ok){const body=await res.json().catch(()=>null);throw new Error(body?.message||`API error ${res.status}`)}return res.status===204?null:res.json()}
