const statusClass=(s:string)=>s.includes('حل')||s.includes('بسته')?'done':s.includes('انتظار')?'waiting':s.includes('بررسی')?'review':'open'
const priorityClass=(p:string)=>p==='بحرانی'?'critical':p==='زیاد'?'high':p==='متوسط'?'medium':'low'
function Stat({icon:Icon,label,value,sub,tone='blue'}:{icon:any;label:string;value:string;sub:string;tone?:string}){return <div className={'statCard '+tone}><div className="statIcon"><Icon size={21}/></div><div className="statText"><span>{label}</span><strong>{value}</strong><small>{sub}</small></div><div className="statSpark">━━━</div></div>}
function Panel({title,sub,action,onAction,children,className=''}:{title:string;sub?:string;action?:string;onAction?:()=>void;children:any;className?:string}){return <section className={'panel '+className}><div className="panelHead"><div><h2>{title}</h2>{sub&&<small>{sub}</small>}</div>{action&&<button className="linkBtn" onClick={onAction}>{action}<ArrowLeft size={14}/></button>}</div>{children}</section>}
function PageHeader({title,sub,action,onAction}:{title:string;sub?:string;action?:string;onAction?:()=>void}){return <div className="pageHeader"><div><div className="eyebrow">NOVISOFT ITSM</div><h1>{title}</h1>{sub&&<p>{sub}</p>}</div>{action&&<button className="newBtn" onClick={onAction}><Plus size={18}/>{action}</button>}</div>}
function TicketTable({rows,onOpen}:{rows:TicketItem[];onOpen:(t:TicketItem)=>void}){return <div className="tableWrap"><table><thead><tr><th>#</th><th>عنوان</th><th>درخواست‌کننده</th><th>واحد</th><th>وضعیت</th><th>اولویت</th><th>آخرین بروزرسانی</th></tr></thead><tbody>{rows.map(t=><tr key={t.id} onClick={()=>onOpen(t)}><td>#{t.id}</td><td className="titleCell"><b>{t.title}</b><small>{t.category} • {t.service}</small></td><td>{t.requester}</td><td>{t.department}</td><td><span className={'pill '+statusClass(t.status)}>{t.status}</span></td><td><span className={'pill '+priorityClass(t.priority)}>{t.priority}</span></td><td>{t.updated}</td></tr>)}</tbody></table></div>}
function Trend(){return <div className="trend"><svg viewBox="0 0 620 190" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#2d72f0" stopOpacity=".25"/><stop offset="1" stopColor="#2d72f0" stopOpacity="0"/></linearGradient></defs><path d="M0 160 L100 128 L200 116 L300 90 L400 112 L500 50 L620 30 L620 190 L0 190Z" fill="url(#area)"/><path d="M0 160 L100 128 L200 116 L300 90 L400 112 L500 50 L620 30" fill="none" stroke="#2d72f0" strokeWidth="3"/><path d="M0 171 L100 155 L200 140 L300 140 L400 128 L500 115 L620 95" fill="none" stroke="#19b77a" strokeWidth="2"/></svg><div className="axis"><span>۷ مهر</span><span>۸ مهر</span><span>۹ مهر</span><span>۱۰ مهر</span><span>۱۱ مهر</span><span>۱۲ مهر</span><span>۱۳ مهر</span></div><div className="chartLegend"><span><i className="blue"/>کل تیکت‌ها</span><span><i className="green"/>حل‌شده</span><span><i className="lightBlue"/>تیکت‌های باز</span></div></div>}
function Donut({type='status'}:{type?:string}){const priority=type==='priority';const rows=priority?[['کم','64','50%','green'],['متوسط','38','30%','blue'],['زیاد','20','16%','yellow'],['بحرانی','6','4%','red']]:[['حل شده','98','76%','green'],['در انتظار پاسخ','18','14%','yellow'],['باز','12','9%','blue'],['در حال بررسی','1','1%','purple'],['بسته','1','1%','red']];return <div className={'donutWrap '+(priority?'priorityWrap':'')}><div className={'donut '+(priority?'priorityDonut':'')}><div><strong>128</strong><span>کل تیکت‌ها</span><small>{priority?'بر اساس اولویت':'بر اساس وضعیت'}</small></div></div><div className="donutLegend">{rows.map(x=><div key={x[0]}><span><i className={x[3]}/>{x[0]}</span><b>{x[1]} <small>({x[2]})</small></b></div>)}</div></div>}
function Bars({rows=[['فناوری اطلاعات','35','27%'],['اداری و مالی','28','22%'],['تولید','20','16%'],['فروش و بازاریابی','15','12%'],['منابع انسانی','12','9%'],['سایر','18','14%']]}:{rows?:string[][]}){return <div className="barsList">{rows.map(r=><div className="barRow" key={r[0]}><span>{r[0]}</span><div className="bar"><i style={{width:r[2]}}/></div><b>{r[1]}</b><small>{r[2]}</small></div>)}</div>}
function Agents(){return <div className="agentList">{[['علی رضایی','AR','28'],['رضا کریمی','RK','24'],['سارا حسینی','SH','18'],['مهدی احمدی','MA','16'],['نگین رضایی','NR','14']].map(x=><div className="agentRow" key={x[0]}><span className="agentAvatar">{x[1]}</span><b>{x[0]}</b><div className="agentBar"><i style={{width:`${Number(x[2])/28*100}%`}}/></div><strong>{x[2]}</strong></div>)}</div>}
function MiniMetric({icon:Icon,title,value,sub,tone='green'}:{icon:any;title:string;value:string;sub:string;tone?:string}){return <div className="miniMetric"><div className={'metricIcon '+tone}><Icon size={19}/></div><span>{title}</span><strong>{value}</strong><small className={tone}>{sub}</small></div>}
function Dashboard({tickets,onOpen,onNavigate}:{tickets:TicketItem[];onOpen:(t:TicketItem)=>void;onNavigate:(p:string)=>void}){return <><div className="hero"><div><div className="eyebrow">NOVISOFT ITSM • SERVICE DESK</div><h1>به نووی سافت خوش آمدید <span>🙌</span></h1><p>نمای کلی عملکرد، وضعیت درخواست‌ها و شاخص‌های کلیدی خدمات فناوری اطلاعات</p></div><div className="today"><CalendarDays size={17}/><span>امروز</span><b>۱۴۰۵/۰۷/۱۳</b></div></div><div className="statsGrid"><Stat icon={Ticket} label="کل تیکت‌ها" value="128" sub="↑ 12٪ بیشتر"/><Stat icon={AlertTriangle} label="تیکت‌های باز" value="12" sub="20٪ کمتر"/><Stat icon={Clock3} label="در انتظار پاسخ" value="18" sub="↑ ۵ مورد بیشتر" tone="yellow"/><Stat icon={CheckCircle2} label="حل‌شده" value="98" sub="↑ ۱۲٪ بیشتر" tone="green"/><Stat icon={Clock3} label="میانگین زمان حل" value="18 ساعت" sub="↓ ۵۲٪ بهتر" tone="purple"/><Stat icon={AlertTriangle} label="تیکت‌های نقض SLA" value="8" sub="↑ ۳ مورد بیشتر" tone="red"/></div><div className="chartGrid"><Panel title="روند تعداد تیکت‌ها" sub="روند هفت روز اخیر" action="۷ روز اخیر"><Trend/></Panel><Panel title="توزیع وضعیت تیکت‌ها" sub="بر اساس تیکت‌های فعال"><Donut/></Panel><Panel title="تیکت‌ها بر اساس اولویت" sub="تعداد تیکت‌ها"><Donut type="priority"/></Panel></div><div className="analysisGrid"><Panel title="تیکت‌ها بر اساس واحد درخواست‌کننده" sub="توزیع درخواست‌ها در ماه جاری"><Bars/></Panel><Panel title="عملکرد کارشناسان" sub="تعداد تیکت‌های حل‌شده"><Agents/></Panel><div className="metricStack"><MiniMetric icon={CheckCircle2} title="میانگین زمان حل تیکت" value="18 ساعت" sub="↓ 32٪ بهتر"/><MiniMetric icon={Headphones} title="میانگین زمان اولین پاسخ" value="42 دقیقه" sub="↓ 28٪ بهتر" tone="blue"/></div></div><div className="bottomGrid"><Panel title="تیکت‌های نزدیک به نقض SLA" sub="تیکت‌هایی که نیاز به اقدام فوری دارند" action="مشاهده همه" onAction={()=>onNavigate('sla')}><CompactRows rows={tickets.slice(0,4)} mode="risk"/></Panel><Panel title="تیکت‌های بحرانی" sub="اولویت بالا برای رسیدگی فوری" action="مشاهده همه" onAction={()=>onNavigate('incidents')}><CompactRows rows={tickets.filter(t=>t.priority==='بحرانی'||t.priority==='زیاد').slice(0,4)} mode="critical"/></Panel><Panel title="آخرین تیکت‌ها" sub="آخرین درخواست‌های ثبت‌شده" action="مشاهده همه" onAction={()=>onNavigate('tickets')}><TicketTable rows={tickets.slice(0,4)} onOpen={onOpen}/></Panel></div></>}
function CompactRows({rows,mode}:{rows:TicketItem[];mode:'risk'|'critical'}){return <div className="compactTable">{rows.map((t,i)=><div className="compactRow" key={t.id}><b>#{t.id}</b><span>{t.title}</span><em className={priorityClass(t.priority)}>{mode==='risk'?'نزدیک SLA':t.priority}</em><small>{mode==='risk'?`${i+1} ساعت` : t.requester}</small></div>)}</div>}

function FilterBar({q,setQ,status,setStatus,priority,setPriority,department,setDepartment,category,setCategory}:{q:string;setQ:(x:string)=>void;status:string;setStatus:(x:string)=>void;priority:string;setPriority:(x:string)=>void;department:string;setDepartment:(x:string)=>void;category:string;setCategory:(x:string)=>void}){return <div className="filterBar"><div className="filterSearch"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="جستجو در عنوان، شماره یا درخواست‌کننده..."/></div><div className="filters"><Filter size={17}/><select value={status} onChange={e=>setStatus(e.target.value)}><option>همه وضعیت‌ها</option><option>باز</option><option>در حال بررسی</option><option>در انتظار کاربر</option><option>در انتظار تأیید</option><option>حل شده</option><option>بسته شده</option></select><select value={priority} onChange={e=>setPriority(e.target.value)}><option>همه اولویت‌ها</option><option>بحرانی</option><option>زیاد</option><option>متوسط</option><option>کم</option></select><select value={department} onChange={e=>setDepartment(e.target.value)}><option>همه واحدها</option><option>مالی</option><option>تولید</option><option>فروش</option><option>منابع انسانی</option><option>انبار</option></select><select value={category} onChange={e=>setCategory(e.target.value)}><option>همه دسته‌ها</option><option>شبکه</option><option>نرم‌افزار</option><option>تجهیزات</option><option>دسترسی</option></select></div></div>}
function ListPage({title,rows,status,priority,department,category,setStatus,setPriority,setDepartment,setCategory,onOpen,onNew,subtitle='مدیریت و پیگیری درخواست‌های کاربران'}:{title:string;rows:TicketItem[];status:string;priority:string;department:string;category:string;setStatus:(x:string)=>void;setPriority:(x:string)=>void;setDepartment:(x:string)=>void;setCategory:(x:string)=>void;onOpen:(x:TicketItem)=>void;onNew:()=>void;subtitle?:string}){return <><PageHeader title={title} sub={subtitle} action="ثبت تیکت" onAction={onNew}/><Panel title="فهرست تیکت‌ها" sub={`${rows.length} مورد یافت شد`}><FilterBar {...{q:'',setQ:()=>{},status,setStatus,priority,setPriority,department,setDepartment,category,setCategory}}/><TicketTable rows={rows} onOpen={onOpen}/></Panel></>}
function NewTicket({onCancel,onCreate}:{onCancel:()=>void;onCreate:(x:Omit<TicketItem,'id'|'updated'|'sla'>)=>void}){const [form,setForm]=useState({title:'',desc:'',requester:'محمدرضا',department:'فناوری اطلاعات',service:'شبکه و اینترنت',category:'شبکه',priority:'متوسط',impact:'متوسط',urgency:'متوسط',assignee:'تخصیص خودکار'});const set=(k:string,v:string)=>setForm({...form,[k]:v});return <><PageHeader title="ثبت تیکت جدید" sub="اطلاعات را کامل کنید تا تیکت سریع‌تر و دقیق‌تر به تیم مربوطه ارجاع شود."/><div className="formLayout"><div className="panel form"><div className="sectionTitle"><Ticket/><div><h2>اطلاعات اصلی</h2><p>فیلدهای ضروری برای ثبت درخواست</p></div></div><label>عنوان تیکت <input value={form.title} onChange={e=>set('title',e.target.value)} placeholder="مثلاً: عدم اتصال سیستم حسابداری به شبکه"/></label><div className="formGrid three"><label>درخواست‌کننده<select value={form.requester} onChange={e=>set('requester',e.target.value)}><option>محمدرضا</option><option>رضا کریمی</option><option>سارا حسینی</option></select></label><label>واحد سازمانی<select value={form.department} onChange={e=>set('department',e.target.value)}><option>فناوری اطلاعات</option><option>مالی</option><option>تولید</option><option>فروش</option><option>منابع انسانی</option><option>انبار</option></select></label><label>خدمت<select value={form.service} onChange={e=>set('service',e.target.value)}><option>شبکه و اینترنت</option><option>نرم‌افزار</option><option>تجهیزات IT</option><option>دسترسی و حساب کاربری</option></select></label></div><div className="formGrid three"><label>دسته‌بندی<select value={form.category} onChange={e=>set('category',e.target.value)}><option>شبکه</option><option>نرم‌افزار</option><option>تجهیزات</option><option>دسترسی</option><option>سرویس</option></select></label><label>اولویت<select value={form.priority} onChange={e=>set('priority',e.target.value)}><option>کم</option><option>متوسط</option><option>زیاد</option><option>بحرانی</option></select></label><label>کارشناس<select value={form.assignee} onChange={e=>set('assignee',e.target.value)}><option>تخصیص خودکار</option><option>علی رضایی</option><option>رضا کریمی</option><option>سارا حسینی</option></select></label></div><div className="formGrid two"><label>اثرگذاری<select value={form.impact} onChange={e=>set('impact',e.target.value)}><option>کم</option><option>متوسط</option><option>زیاد</option><option>بحرانی</option></select></label><label>فوریت<select value={form.urgency} onChange={e=>set('urgency',e.target.value)}><option>کم</option><option>متوسط</option><option>زیاد</option><option>بحرانی</option></select></label></div><label>شرح کامل درخواست <textarea value={form.desc} onChange={e=>set('desc',e.target.value)} rows={7} placeholder="شرح مشکل، زمان شروع، کاربران متاثر و هر اطلاعاتی که به حل سریع‌تر کمک می‌کند..."/></label><div className="formHint"><CheckCircle2 size={17}/><span>اولویت نهایی می‌تواند بر اساس اثرگذاری و فوریت توسط سیستم محاسبه شود.</span></div><div className="formActions"><button className="ghost" onClick={onCancel}>انصراف</button><button className="newBtn" disabled={!form.title.trim()||!form.desc.trim()} onClick={()=>onCreate({title:form.title,status:'باز',priority:form.priority,requester:form.requester,assignee:form.assignee==='تخصیص خودکار'?'تخصیص نشده':form.assignee,category:form.category,department:form.department,service:form.service,description:form.desc})}><Check/>ثبت تیکت</button></div></div><aside className="panel sideInfo"><h2>راهنمای ثبت تیکت</h2><InfoItem icon={Shield} title="اطلاعات کافی" text="شرح دقیق باعث کاهش زمان رفت و برگشت تیکت می‌شود."/><InfoItem icon={Clock3} title="SLA" text="بعد از ثبت، زمان پاسخ و حل بر اساس خدمت و اولویت تعیین می‌شود."/><InfoItem icon={Users} title="ارجاع خودکار" text="تیکت بر اساس خدمت و واحد به تیم مناسب ارسال می‌شود."/></aside></div></>}
function InfoItem({icon:Icon,title,text}:{icon:any;title:string;text:string}){return <div className="infoItem"><div className="settingIcon"><Icon size={18}/></div><div><b>{title}</b><p>{text}</p></div></div>}

function ModuleShell({title,sub,children,action,onAction}:{title:string;sub:string;children:any;action?:string;onAction?:()=>void}){return <><PageHeader title={title} sub={sub} action={action} onAction={onAction}/><div className="moduleGrid">{children}</div></>}
function DataRows({rows}:{rows:{id:string;title:string;meta:string;status:string;tag:string}[]}){return <div className="dataRows">{rows.map(r=><div className="dataRow" key={r.id}><div className="rowIcon"><CircleDotIcon/></div><div className="rowMain"><b>{r.title}</b><small>{r.meta}</small></div><span className="rowId">{r.id}</span><span className={'pill '+statusClass(r.status)}>{r.status}</span><span className="rowTag">{r.tag}</span><button className="rowMore"><MoreHorizontal size={18}/></button></div>)}</div>}
function CircleDotIcon(){return <span className="dotCircle"/>}
function IncidentsPage({notify}:{notify:(s:string)=>void}){const rows=[{id:'INC-204',title:'اختلال شبکه مالی',meta:'مالی • 10 دقیقه پیش',status:'باز',tag:'بحرانی'},{id:'INC-203',title:'قطعی اینترنت طبقه دوم',meta:'تولید • 2 ساعت پیش',status:'در حال بررسی',tag:'زیاد'},{id:'INC-202',title:'اختلال سرویس چاپ',meta:'انبار • امروز',status:'حل شده',tag:'متوسط'}];return <ModuleShell title="رخدادها" sub="ثبت، اولویت‌بندی، بررسی و رفع رخدادهای سرویس" action="ثبت رخداد" onAction={()=>notify('فرم ثبت رخداد آماده شد')}><div className="summaryGrid"><Stat icon={AlertTriangle} label="رخدادهای باز" value="12" sub="3 مورد بحرانی" tone="red"/><Stat icon={Clock3} label="میانگین رفع" value="2:18" sub="ساعت" tone="blue"/></div><Panel title="فهرست رخدادها" sub="آخرین رخدادهای ثبت‌شده"><div className="miniFilters"><button className="active">همه</button><button>بحرانی</button><button>باز</button><button>در حال بررسی</button><button>حل شده</button></div><DataRows rows={rows}/></Panel><Panel title="اقدام‌های سریع"><div className="actionGrid"><button onClick={()=>notify('رخداد جدید ایجاد شد')}><Plus/>ایجاد رخداد</button><button onClick={()=>notify('رخدادهای بحرانی فیلتر شدند')}><AlertTriangle/>بحرانی‌ها</button><button onClick={()=>notify('گزارش رخدادها آماده شد')}><BarChart3/>گزارش رخداد</button></div></Panel></ModuleShell>}
function RequestsPage({notify}:{notify:(s:string)=>void}){const rows=[{id:'REQ-781',title:'ایجاد دسترسی VPN',meta:'فناوری اطلاعات • امروز',status:'در انتظار تأیید',tag:'دسترسی'},{id:'REQ-780',title:'نصب نرم‌افزار حسابداری',meta:'مالی • امروز',status:'در حال بررسی',tag:'نرم‌افزار'},{id:'REQ-779',title:'درخواست لپ‌تاپ جدید',meta:'منابع انسانی • دیروز',status:'حل شده',tag:'تجهیزات'}];return <ModuleShell title="درخواست خدمات" sub="مدیریت Service Requestها و درخواست‌های استاندارد" action="درخواست جدید" onAction={()=>notify('فرم درخواست خدمات آماده شد')}><div className="summaryGrid"><Stat icon={ShoppingCart} label="درخواست‌های باز" value="24" sub="8 مورد امروز"/><Stat icon={CheckCircle2} label="نرخ تکمیل" value="91٪" sub="این ماه" tone="green"/></div><Panel title="درخواست‌های اخیر" sub="بر اساس آخرین بروزرسانی"><div className="miniFilters"><button className="active">همه درخواست‌ها</button><button>در انتظار تأیید</button><button>در حال انجام</button><button>تکمیل شده</button></div><DataRows rows={rows}/></Panel><Panel title="دسته‌بندی خدمات"><div className="serviceTiles">{[[MonitorCog,'نرم‌افزار','18 درخواست'],[Package,'تجهیزات','12 درخواست'],[KeyRound,'دسترسی','9 درخواست'],[Network,'شبکه','7 درخواست']].map(([I,t,s])=>{const Icon=I as any;return <button key={t as string} onClick={()=>notify(`دسته ${t} انتخاب شد`)}><Icon/><b>{t as string}</b><small>{s as string}</small></button>})}</div></Panel></ModuleShell>}
function ProblemsPage(){return <ModuleShell title="مشکلات" sub="Problem Management، RCA و جلوگیری از تکرار رخدادها"><div className="summaryGrid"><Stat icon={Wrench} label="مشکلات فعال" value="7" sub="2 مورد بحرانی" tone="yellow"/><Stat icon={Activity} label="مشکل‌های ریشه‌ای" value="18" sub="این فصل"/></div><Panel title="فهرست مشکلات"><DataRows rows={[{id:'PRB-44',title:'قطعی‌های تکراری شبکه مالی',meta:'علت ریشه‌ای در حال بررسی',status:'تحلیل',tag:'RCA'},{id:'PRB-43',title:'خطای مکرر چاپ انبار',meta:'راهکار موقت فعال',status:'در حال اقدام',tag:'Workaround'},{id:'PRB-42',title:'کندی سرویس ERP',meta:'جلسه بررسی با تأمین‌کننده',status:'باز',tag:'Vendor'}]}/></Panel><Panel title="چرخه Problem Management"><div className="workflow"><span>ثبت مشکل</span><i>→</i><span>تحلیل RCA</span><i>→</i><span>راهکار موقت</span><i>→</i><span>حل ریشه‌ای</span><i>→</i><span>بستن</span></div></Panel></ModuleShell>}
function ChangesPage({notify}:{notify:(s:string)=>void}){return <ModuleShell title="تغییرات" sub="برنامه‌ریزی، ارزیابی ریسک و اجرای Changeها"><div className="summaryGrid"><Stat icon={GitBranch} label="تغییرات در انتظار" value="6" sub="2 نیازمند تأیید"/><Stat icon={Shield} label="موفقیت تغییرات" value="96٪" sub="30 روز اخیر" tone="green"/></div><Panel title="تقویم تغییرات"><div className="changeTimeline">{[['شنبه 14 مهر','ارتقای سرور ERP','22:00 - 23:30'],['یکشنبه 15 مهر','بروزرسانی فایروال','18:00 - 19:00'],['سه‌شنبه 17 مهر','تعویض سوئیچ طبقه دوم','20:00 - 21:00']].map(x=><div key={x[0]}><b>{x[0]}</b><span>{x[1]}</span><em>{x[2]}</em></div>)}</div></Panel><Panel title="اقدامات"><div className="actionGrid"><button onClick={()=>notify('تغییر جدید ایجاد شد')}><Plus/>ثبت تغییر جدید</button><button onClick={()=>notify('تغییرات در انتظار تأیید نمایش داده شد')}><Check/>تایید تغییرات</button><button onClick={()=>notify('گزارش تغییرات آماده شد')}><FileText/>گزارش تغییرات</button></div></Panel></ModuleShell>}
function ServicesPage({notify}:{notify:(s:string)=>void}){return <ModuleShell title="کاتالوگ خدمات" sub="سرویس‌های قابل درخواست برای کارکنان سازمان"><Panel title="سرویس‌های نووی سافت"><div className="catalogGrid">{[[KeyRound,'دسترسی و حساب کاربری','ایجاد، حذف و تغییر دسترسی'],[MonitorCog,'تجهیزات IT','لپ‌تاپ، مانیتور و تجهیزات'],[Wifi,'شبکه و اینترنت','اتصال، VPN و شبکه'],[Package,'نرم‌افزار','نصب و پشتیبانی نرم‌افزار'],[Shield,'امنیت اطلاعات','گزارش رخداد امنیتی'],[Server,'سرویس‌های سازمانی','ERP، اتوماسیون و سرویس‌ها']].map(([I,t,d])=>{const Icon=I as any;return <button key={t as string} className="catalogCard" onClick={()=>notify(`سرویس «${t}» انتخاب شد`)}><Icon/><b>{t as string}</b><small>{d as string}</small><ArrowLeft size={15}/></button>})}</div></Panel></ModuleShell>}
function SlaPage({notify}:{notify:(s:string)=>void}){return <ModuleShell title="SLA و گردش کار" sub="تعریف سطح خدمت، زمان پاسخ، زمان حل و Escalation" action="ایجاد قانون SLA" onAction={()=>notify('فرم قانون SLA جدید آماده شد')}><div className="summaryGrid"><Stat icon={Clock3} label="مطابق SLA" value="94٪" sub="هدف 95٪" tone="green"/><Stat icon={AlertTriangle} label="نقض SLA" value="8" sub="این ماه" tone="red"/></div><Panel title="قوانین SLA فعال" sub="قابل تنظیم بر اساس خدمت و اولویت"><div className="slaCards">{[['پشتیبانی عادی','اولین پاسخ 60 دقیقه','حل 8 ساعت','94٪'],['درخواست خدمات','اولین پاسخ 30 دقیقه','حل 4 ساعت','92٪'],['رخداد بحرانی','اولین پاسخ 10 دقیقه','حل 1 ساعت','96٪'],['شبکه','اولین پاسخ 15 دقیقه','حل 2 ساعت','94٪']].map(x=><div key={x[0]}><b>{x[0]}</b><span>{x[1]}</span><span>{x[2]}</span><strong>{x[3]}</strong><button onClick={()=>notify(`ویرایش SLA «${x[0]}»`)}>ویرایش</button></div>)}</div></Panel><Panel title="گردش‌کارهای فعال"><DataRows rows={[{id:'WF-01',title:'Escalation تیکت بحرانی',meta:'پس از 30 دقیقه بدون پاسخ',status:'فعال',tag:'30 دقیقه'},{id:'WF-02',title:'یادآوری تیکت در انتظار کاربر',meta:'پس از 8 ساعت',status:'فعال',tag:'8 ساعت'},{id:'WF-03',title:'بستن خودکار تیکت حل‌شده',meta:'پس از 48 ساعت',status:'فعال',tag:'48 ساعت'}]}/></Panel></ModuleShell>}
function ApprovalsPage(){return <ModuleShell title="تاییدیه‌ها" sub="درخواست‌هایی که برای ادامه نیازمند تایید هستند"><div className="summaryGrid"><Stat icon={CheckCircle2} label="در انتظار تایید" value="9" sub="3 مورد فوری" tone="yellow"/></div><Panel title="صف تاییدیه"><DataRows rows={[{id:'APR-88',title:'دسترسی VPN مدیر مالی',meta:'درخواست‌کننده: محمدرضا • 12 دقیقه پیش',status:'در انتظار',tag:'فوری'},{id:'APR-87',title:'خرید لپ‌تاپ جدید',meta:'منابع انسانی • 1 ساعت پیش',status:'در انتظار',tag:'مالی'},{id:'APR-86',title:'تغییر فایروال',meta:'شبکه • امروز',status:'در انتظار',tag:'تغییر'}]}/></Panel><div className="actionGrid"><button><Check/>تایید</button><button><X/>رد درخواست</button><button><Eye/>مشاهده جزئیات</button></div></ModuleShell>}
function KnowledgePage({notify}:{notify:(s:string)=>void}){return <ModuleShell title="پایگاه دانش" sub="راهنماها و مقالات قابل استفاده برای کاربران و کارشناسان"><Panel title="جستجو در پایگاه دانش"><div className="knowledgeSearch"><Search/><input placeholder="مثلاً: بازیابی رمز عبور، VPN، چاپگر..."/><button className="newBtn" onClick={()=>notify('جستجوی پایگاه دانش انجام شد')}>جستجو</button></div></Panel><Panel title="مقالات محبوب"><DataRows rows={[{id:'KB-102',title:'راهنمای بازیابی رمز عبور ویندوز',meta:'آخرین بروزرسانی: امروز • 248 مشاهده',status:'منتشر شده',tag:'محبوب'},{id:'KB-101',title:'راهنمای اتصال VPN سازمان',meta:'آخرین بروزرسانی: دیروز • 193 مشاهده',status:'منتشر شده',tag:'شبکه'},{id:'KB-099',title:'حل مشکل چاپگرهای شبکه',meta:'آخرین بروزرسانی: 3 روز پیش • 151 مشاهده',status:'منتشر شده',tag:'سخت‌افزار'}]}/></Panel><button className="newBtn wideBtn" onClick={()=>notify('مقاله جدید ایجاد شد')}><Plus/>ایجاد مقاله</button></ModuleShell>}
function AssetsPage(){return <ModuleShell title="دارایی‌ها و CMDB" sub="مدیریت تجهیزات، Configuration Itemها و ارتباط سرویس‌ها"><div className="summaryGrid"><Stat icon={MonitorCog} label="دارایی‌های ثبت‌شده" value="486" sub="98٪ دارای مالک"/><Stat icon={Server} label="سرورها" value="42" sub="3 نیازمند اقدام"/></div><Panel title="آخرین دارایی‌ها"><DataRows rows={[{id:'AST-486',title:'Laptop • HP ProBook',meta:'محمدرضا • مالی • خرید 1404',status:'فعال',tag:'Laptop'},{id:'AST-485',title:'Server • ERP-01',meta:'مرکز داده • Dell R740',status:'فعال',tag:'Server'},{id:'AST-484',title:'Switch • Floor-2',meta:'شبکه • Cisco 2960',status:'فعال',tag:'Network'}]}/></Panel><div className="actionGrid"><button><Plus/>ثبت دارایی</button><button><RefreshCw/>اسکن CMDB</button><button><Download/>خروجی گزارش</button></div></ModuleShell>}

function UsersPage({notify}:{notify:(s:string)=>void}){const [tab,setTab]=useState<'users'|'units'>('users');const [users,setUsers]=useState([['USR-318','رضا کریمی','شبکه','فعال'],['USR-317','سارا حسینی','نرم‌افزار','فعال'],['USR-316','نگین رضایی','مدیر','فعال']]);const [units,setUnits]=useState(['فناوری اطلاعات','مالی','تولید','فروش','منابع انسانی','انبار']);const [newUser,setNewUser]=useState('');const [newUnit,setNewUnit]=useState('');return <><PageHeader title="کاربران و تیم‌ها" sub="مدیریت کاربران، واحدها، تیم‌های پشتیبانی و نقش‌های دسترسی"/><div className="tabs"><button className={tab==='users'?'active':''} onClick={()=>setTab('users')}><Users/>کاربران</button><button className={tab==='units'?'active':''} onClick={()=>setTab('units')}><Building2/>واحدهای سازمانی</button></div>{tab==='users'?<><Panel title="کاربران سیستم" sub={`${users.length} کاربر فعال`}><div className="inlineCreate"><input value={newUser} onChange={e=>setNewUser(e.target.value)} placeholder="نام کاربر جدید..."/><select><option>شبکه</option><option>نرم‌افزار</option><option>مدیر</option></select><button className="newBtn" onClick={()=>{if(newUser.trim()){setUsers([[`USR-${320+users.length}`,newUser,'شبکه','فعال'],...users]);setNewUser('');notify('کاربر جدید اضافه شد')}}}><Plus/>افزودن کاربر</button></div><div className="userTable">{users.map(u=><div className="userRow" key={u[0]}><div className="avatar">{u[1][0]}</div><div><b>{u[1]}</b><small>{u[0]} • تیم {u[2]}</small></div><span className="pill done">{u[3]}</span><button><MoreHorizontal/></button></div>)}</div></Panel><Panel title="تیم‌های پشتیبانی"><div className="teamGrid"><div className="teamCard"><Users/><b>شبکه</b><span>4 کارشناس • 38 تیکت</span></div><div className="teamCard"><MonitorCog/><b>نرم‌افزار</b><span>4 کارشناس • 41 تیکت</span></div><div className="teamCard"><Shield/><b>امنیت</b><span>3 کارشناس • 17 تیکت</span></div></div></Panel></>:<Panel title="واحدهای سازمانی" sub="واحدها در زمان ثبت تیکت و گزارش‌ها قابل انتخاب خواهند بود"><div className="inlineCreate"><input value={newUnit} onChange={e=>setNewUnit(e.target.value)} placeholder="نام واحد جدید..."/><button className="newBtn" onClick={()=>{if(newUnit.trim()){setUnits([newUnit,...units]);setNewUnit('');notify('واحد سازمانی اضافه شد')}}}><Plus/>افزودن واحد</button></div><div className="unitGrid">{units.map((u,i)=><div className="unitCard" key={u}><Building2/><div><b>{u}</b><small>{i%2===0?'32':'18'} کاربر</small></div><MoreHorizontal/></div>)}</div></Panel>}</>}
function ReportsPage({notify}:{notify:(s:string)=>void}){return <ModuleShell title="گزارشات و KPI" sub="گزارش‌های مدیریتی، عملکرد کارشناسان و شاخص‌های میز خدمت"><Panel title="گزارش‌های آماده"><div className="reportGrid">{[['گزارش عملکرد میز خدمت',BarChart3],['گزارش SLA',Clock3],['گزارش کارشناسان',Users],['گزارش رخدادها',AlertTriangle],['گزارش رضایت کاربران',Activity],['گزارش دارایی‌ها',Server]].map(([t,I])=>{const Icon=I as any;return <button key={t as string} onClick={()=>notify(`گزارش «${t}» تولید شد`)}><Icon/><b>{t as string}</b><small>تولید گزارش و خروجی Excel</small><Download size={14}/></button>})}</div></Panel><div className="chartGrid"><Panel title="KPI ماهانه"><Bars rows={[['حل در SLA','94','94%'],['رضایت کاربران','91','91%'],['First Response','88','88%'],['Resolution','86','86%']]}/></Panel><Panel title="توزیع وضعیت"><Donut/></Panel></div></ModuleShell>}
function NotificationsPage({notify}:{notify:(s:string)=>void}){return <ModuleShell title="اعلان‌ها" sub="هشدارها، رویدادهای سیستمی و پیام‌های میز خدمت"><Panel title="اعلان‌های اخیر"><div className="notificationList">{[['red','نقض SLA','تیکت #1042 در آستانه نقض SLA است','2 دقیقه پیش'],['yellow','تاییدیه','درخواست دسترسی VPN منتظر تایید شماست','18 دقیقه پیش'],['blue','تیکت جدید','تیکت #1043 توسط واحد مالی ثبت شد','35 دقیقه پیش'],['green','حل تیکت','تیکت #1040 با موفقیت حل شد','1 ساعت پیش']].map(x=><div className="notificationItem" key={x[1]}><span className={'notificationDot '+x[0]}/><div><b>{x[1]}</b><p>{x[2]}</p><small>{x[3]}</small></div><button onClick={()=>notify('اعلان خوانده شد')}><Check/></button></div>)}</div></Panel><div className="actionGrid"><button onClick={()=>notify('همه اعلان‌ها خوانده شدند')}><Check/>خواندن همه</button><button onClick={()=>notify('اعلان‌ها بروزرسانی شدند')}><RefreshCw/>تازه‌سازی</button></div></ModuleShell>}
function SettingsPage({notify,dark,setDark}:{notify:(s:string)=>void;dark:boolean;setDark:(v:boolean)=>void}){const [tab,setTab]=useState('general');const tabs=[['general','عمومی',Settings],['ticket','تیکت‌ها',Ticket],['sla','SLA',Clock3],['workflow','گردش کار',Workflow],['catalog','کاتالوگ',Boxes],['notifications','اعلان‌ها',Bell],['security','امنیت',Shield]];return <><PageHeader title="تنظیمات" sub="مرکز مدیریت تنظیمات سازمان، تیکتینگ، SLA، گردش‌کار، امنیت و اعلان‌ها"/><div className="settingsLayout"><aside className="settingsTabs">{tabs.map(([id,t,I])=>{const Icon=I as any;return <button className={tab===id?'active':''} key={id as string} onClick={()=>setTab(id as string)}><Icon size={18}/>{t as string}</button>})}</aside><div className="settingsBody">{tab==='general'&&<><Panel title="تنظیمات عمومی"><div className="settingsList"><SettingRow icon={Building2} title="نام سازمان" sub="نامی که در سیستم نمایش داده می‌شود" action={<input className="inlineInput" defaultValue="سازمان دوماس"/>}/><SettingRow icon={CalendarDays} title="تقویم کاری" sub="شنبه تا چهارشنبه، 08:00 تا 16:00" action={<button className="ghost" onClick={()=>notify('تقویم کاری آماده ویرایش است')}>ویرایش</button>}/><SettingRow icon={Users} title="مدیریت واحدها و کاربران" sub="افزودن واحد، کاربر و تیم پشتیبانی" action={<button className="ghost" onClick={()=>notify('از منوی کاربران و تیم‌ها استفاده کنید')}>باز کردن</button>}/><SettingRow icon={Shield} title="سطح دسترسی پیش‌فرض" sub="نقش پایه کاربران جدید" action={<select className="inlineSelect"><option>کاربر عادی</option><option>کارشناس</option><option>مدیر</option></select>}/><SettingRow icon={MonitorCog} title="حالت نمایش" sub="انتخاب ظاهر روشن یا تاریک برای پنل مدیریت" action={<div className="themeChoice"><button className={!dark?'active':''} onClick={()=>setDark(false)}>روشن</button><button className={dark?'active':''} onClick={()=>setDark(true)}>تاریک</button></div>}/></div></Panel></>}{tab==='ticket'&&<><Panel title="تنظیمات تیکت"><div className="settingsList"><SettingRow icon={Ticket} title="شماره‌گذاری خودکار" sub="ایجاد شماره یکتا برای هر تیکت" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={MessageSquare} title="امکان بازگشایی تیکت" sub="کاربر تا 7 روز پس از حل می‌تواند تیکت را بازگشایی کند" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={FileText} title="الزام شرح درخواست" sub="ثبت تیکت بدون شرح کامل مجاز نباشد" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={PaperclipIcon} title="پیوست اجباری برای رخدادهای بحرانی" sub="برای اولویت بحرانی حداقل یک پیوست" action={<Toggle value={false} setValue={()=>{}}/>}/></div></Panel></>}{tab==='sla'&&<><Panel title="مدیریت SLA"><div className="slaSettingsGrid">{[['بحرانی','10 دقیقه','1 ساعت'],['زیاد','30 دقیقه','4 ساعت'],['متوسط','2 ساعت','8 ساعت'],['کم','4 ساعت','24 ساعت']].map(x=><div key={x[0]}><b>اولویت {x[0]}</b><label>اولین پاسخ<input defaultValue={x[1]}/></label><label>زمان حل<input defaultValue={x[2]}/></label><button className="ghost" onClick={()=>notify(`SLA اولویت ${x[0]} ذخیره شد`)}><Check/>ذخیره</button></div>)}</div></Panel><Panel title="Escalation"><div className="settingsList"><SettingRow icon={AlertTriangle} title="Escalation سطح 1" sub="پس از 80٪ مصرف زمان SLA به سرپرست اطلاع داده شود" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={Bell} title="Escalation سطح 2" sub="پس از 100٪ مصرف SLA به مدیر میز خدمت اطلاع داده شود" action={<Toggle value={true} setValue={()=>{}}/>}/></div></Panel></>}{tab==='workflow'&&<><Panel title="گردش‌کار تیکت"><div className="workflowSettings">{['جدید → تخصیص','تخصیص → در حال بررسی','در حال بررسی → در انتظار کاربر','در انتظار کاربر → حل شده','حل شده → بسته شده'].map((x,i)=><div key={x}><span>{i+1}</span><b>{x}</b><Toggle value={true} setValue={()=>{}}/></div>)}</div></Panel><Panel title="قوانین خودکار"><div className="actionGrid"><button onClick={()=>notify('قانون جدید ایجاد شد')}><Plus/>افزودن قانون</button><button><RefreshCw/>بازنشانی قوانین</button></div></Panel></>}{tab==='catalog'&&<><Panel title="تنظیمات کاتالوگ خدمات"><div className="settingsList"><SettingRow icon={Boxes} title="اجباری بودن انتخاب خدمت" sub="هر تیکت باید به یک خدمت متصل باشد" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={KeyRound} title="دسترسی بر اساس واحد" sub="نمایش سرویس‌ها بر اساس واحد کاربر" action={<Toggle value={true} setValue={()=>{}}/>}/></div></Panel><Panel title="مدیریت دسته‌بندی‌ها"><div className="actionGrid"><button onClick={()=>notify('دسته جدید ایجاد شد')}><Plus/>افزودن دسته</button><button onClick={()=>notify('خدمت جدید ایجاد شد')}><Plus/>افزودن خدمت</button></div></Panel></>}{tab==='notifications'&&<Panel title="اعلان و اتوماسیون"><div className="settingsList"><SettingRow icon={Bell} title="اعلان ایمیلی" sub="ارسال هشدارهای مهم به مدیران" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={MessageSquare} title="اعلان داخل سیستم" sub="نمایش اعلان‌های لحظه‌ای در میز خدمت" action={<Toggle value={true} setValue={()=>{}}/>}/><SettingRow icon={Clock3} title="یادآوری SLA" sub="ارسال یادآوری قبل از نقض SLA" action={<Toggle value={true} setValue={()=>{}}/>}/></div></Panel>}{tab==='security'&&<Panel title="امنیت و دسترسی"><div className="settingsList"><SettingRow icon={Shield} title="ورود دومرحله‌ای" sub="اجبار احراز هویت چندمرحله‌ای برای مدیران" action={<Toggle value={false} setValue={()=>{}}/>}/><SettingRow icon={KeyRound} title="سیاست رمز عبور" sub="حداقل 8 کاراکتر، حروف و عدد" action={<button className="ghost">مدیریت</button>}/><SettingRow icon={Users} title="نقش‌ها و مجوزها" sub="مدیریت RBAC و دسترسی منوها" action={<button className="ghost">مدیریت</button>}/></div></Panel>}{<div className="settingsActions"><button className="newBtn" onClick={()=>notify('تنظیمات ذخیره شد')}><Check/>ذخیره تنظیمات</button><button className="ghost" onClick={()=>notify('تنظیمات بازنشانی شد')}><RefreshCw/>بازنشانی</button></div>}</div></div></>}
function PaperclipIcon(){return <span className="fakeIcon">📎</span>}
function SettingRow({icon:Icon,title,sub,action}:{icon:any;title:string;sub:string;action:any}){return <div className="settingRow"><div className="settingIcon"><Icon size={18}/></div><div><b>{title}</b><small>{sub}</small></div><div className="settingAction">{action}</div></div>}
function Toggle({value,setValue}:{value:boolean;setValue:(x:boolean)=>void}){return <button className={'toggle '+(value?'on':'')} onClick={()=>setValue(!value)}><i/></button>}


