function EnterprisePage({id,notify}:{id:string;notify:(s:string)=>void}){const m=enterpriseModules[id]||{title:'ماژول',sub:'مدیریت اطلاعات سازمان',entity:'رکورد',stats:[['کل','128',''],['باز','18',''],['امروز','24',''],['SLA','94٪','']],tabs:['همه','فعال','باز'],columns:['عنوان','مالک','وضعیت','آخرین بروزرسانی'],rows:[['رکورد نمونه','تیم IT','فعال','امروز'],['رکورد نمونه دوم','پشتیبانی','باز','دیروز']],actions:['رکورد جدید','فیلتر','خروجی','گزارش']};const [tab,setTab]=useState(m.tabs[0]);return <><PageHeader title={m.title} sub={m.sub} action={m.actions[0]} onAction={()=>notify(`${m.actions[0]} در ${m.title} آماده شد`)}/><div className="summaryGrid">{m.stats.map((s,i)=><Stat key={i} icon={[Activity,CheckCircle2,Clock3,BarChart3][i%4]} label={s[0]} value={s[1]} sub={s[2]} tone={s[3]||'blue'}/>)}</div><Panel title={`مدیریت ${m.entity}`} sub={`${m.rows.length} رکورد نمونه • عملیات سریع فعال`}><div className="enterpriseToolbar"><div className="miniFilters">{m.tabs.map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div><div className="tableActions"><button className="ghost" onClick={()=>notify('فیلتر پیشرفته باز شد')}><Filter size={16}/>فیلتر</button><button className="ghost" onClick={()=>notify('داده‌ها به‌روزرسانی شد')}><RefreshCw size={16}/>بروزرسانی</button><button className="ghost" onClick={()=>notify('خروجی آماده شد')}><Download size={16}/>خروجی</button></div></div><div className="tableWrap"><table><thead><tr>{m.columns.map(c=><th key={c}>{c}</th>)}<th>عملیات</th></tr></thead><tbody>{m.rows.map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{j===r.length-1?<span className="pill review">{c}</span>:c}</td>)}<td><button className="rowAction" onClick={()=>notify(`رکورد ${i+1} باز شد`)}><Eye size={16}/></button><button className="rowAction" onClick={()=>notify('منوی عملیات باز شد')}><MoreHorizontal size={16}/></button></td></tr>)}</tbody></table></div></Panel><Panel title="عملیات سریع" sub="عملیات متداول این ماژول"><div className="actionGrid">{m.actions.map((a,i)=><button key={a} onClick={()=>notify(`${a} اجرا شد`)}>{i===0?<Plus/>:i===1?<Workflow/>:i===2?<Download/>:<BarChart3/>}{a}</button>)}</div></Panel></>}

function LoginPage({onLogin}:{onLogin:()=>void}){const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [showPassword,setShowPassword]=useState(false);const [error,setError]=useState('');const [now,setNow]=useState(new Date());useEffect(()=>{const id=window.setInterval(()=>setNow(new Date()),1000);return()=>window.clearInterval(id)},[]);const submit=async(e:any)=>{e.preventDefault();setError('');const isDemo=window.location.hostname.endsWith('.github.io');if(isDemo){if(username.trim()==='admin'&&password==='reza@1382'){sessionStorage.setItem('novisoft-auth','1');sessionStorage.setItem('novisoft-token','demo-token');sessionStorage.setItem('novisoft-user',JSON.stringify({id:1,username:'admin',displayName:'مدیر سیستم',role:'Admin'}));onLogin();}else{setError('نام کاربری یا رمز عبور صحیح نیست.');}return;}try{const base=(import.meta.env.VITE_API_URL||'http://localhost:5000/api').replace(/\/$/,'');const res=await fetch(`${base}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.trim(),password})});if(!res.ok){const data=await res.json().catch(()=>null);throw new Error(data?.message||'نام کاربری یا رمز عبور صحیح نیست.')}const data=await res.json();sessionStorage.setItem('novisoft-auth','1');sessionStorage.setItem('novisoft-token',data.token);sessionStorage.setItem('novisoft-user',JSON.stringify(data.user));onLogin()}catch(err:any){setError(err?.message||'ارتباط با سرور برقرار نشد.');}};const time=new Intl.DateTimeFormat('fa-IR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(now);const date=new Intl.DateTimeFormat('fa-IR',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(now);return <div className="loginPage" dir="rtl"><div className="loginGlow glowOne"/><div className="loginGlow glowTwo"/><div className="loginShell"><section className="loginShowcase"><div className="loginBrand"><img src={`${import.meta.env.BASE_URL}novisoft-logo.png`}/><div><strong>نووی‌سافت</strong><span>Enterprise Service Desk</span></div></div><div className="loginTitle"><span className="typingKicker">NOVISOFT ITSM</span><h1 className="loginAnimatedTitle"><span>نرم‌افزار </span><b>نووی‌سافت</b></h1><p>مرکز یکپارچه مدیریت خدمات فناوری اطلاعات، تیکتینگ، ITSM و CRM سازمان</p></div><div className="loginFeatures"><div><Shield size={18}/><span>امن و سازمانی</span></div><div><Workflow size={18}/><span>فرآیندهای هوشمند</span></div><div><BarChart3 size={18}/><span>تحلیل و گزارش</span></div></div><div className="loginInfo"><div><CalendarDays size={17}/><span>{date}</span></div><div><Clock3 size={17}/><strong>{time}</strong></div><div><span className="statusDot"/>سرویس سامانه فعال است</div></div></section><section className="loginCard"><div className="loginCardLogo"><img src={`${import.meta.env.BASE_URL}novisoft-logo.png`}/><div><b>نووی‌سافت</b><small>سامانه مدیریت خدمات سازمانی</small></div></div><div className="loginWelcome"><h2>خوش آمدید</h2><p>برای ورود به پنل مدیریت، اطلاعات حساب خود را وارد کنید.</p></div><form onSubmit={submit} className="loginForm" autoComplete="off"><label>Username<input dir="ltr" autoFocus value={username} onChange={e=>{setUsername(e.target.value);setError('')}} placeholder="" autoComplete="off"/></label><label>Password<div className="passwordBox"><input dir="ltr" type={showPassword?'text':'password'} value={password} onChange={e=>{setPassword(e.target.value);setError('')}} placeholder="" autoComplete="off"/><button type="button" onClick={()=>setShowPassword(!showPassword)} aria-label="نمایش رمز"><Eye size={17}/></button></div></label>{error&&<div className="loginError"><AlertTriangle size={16}/>{error}</div>}<div className="loginOptions"><label className="remember"><input type="checkbox" defaultChecked/> <span>مرا به خاطر بسپار</span></label><button type="button" onClick={()=>setError('برای بازیابی رمز عبور با مدیر سیستم تماس بگیرید.')}>فراموشی رمز عبور؟</button></div><button className="loginSubmit" type="submit">ورود به سامانه<ArrowLeft size={18}/></button></form><div className="loginSecurity"><Shield size={15}/><span>اتصال امن • دسترسی کنترل‌شده • نسخه 8.0 Enterprise</span></div><div className="loginFooter">© نووی‌سافت • تمامی حقوق محفوظ است</div></section></div></div>}

function App(){const [authenticated,setAuthenticated]=useState(()=>sessionStorage.getItem('novisoft-auth')==='1');const [page,setPage]=useState('dashboard');const [dark,setDark]=useState(()=>localStorage.getItem('novisoft-theme')==='dark');const [tickets,setTickets]=useState(seed);const [q,setQ]=useState('');const [selected,setSelected]=useState<TicketItem|null>(null);const [toast,setToast]=useState('');const [open,setOpen]=useState(false);const [openNavGroup,setOpenNavGroup]=useState('');const [status,setStatus]=useState('همه وضعیت‌ها');const [priority,setPriority]=useState('همه اولویت‌ها');const [department,setDepartment]=useState('همه واحدها');const [category,setCategory]=useState('همه دسته‌ها');const filtered=useMemo(()=>tickets.filter(t=>(status==='همه وضعیت‌ها'||t.status===status)&&(priority==='همه اولویت‌ها'||t.priority===priority)&&(department==='همه واحدها'||t.department===department)&&(category==='همه دسته‌ها'||t.category===category)&&`${t.id} ${t.title} ${t.requester} ${t.assignee} ${t.category} ${t.department}`.toLowerCase().includes(q.toLowerCase())),[tickets,status,priority,department,category,q]);useEffect(()=>{if(!authenticated)return;apiFetch('/tickets').then((rows:any[])=>{if(Array.isArray(rows)&&rows.length){setTickets(rows.map((x:any)=>({id:x.id,title:x.title,status:x.status,priority:x.priority,requester:x.requester,assignee:x.assignee,category:x.category,updated:new Date(x.updatedAt).toLocaleString('fa-IR'),sla:x.sla,department:x.department,service:x.service,description:x.description})))}}).catch(()=>{});},[authenticated]);const notify=(m:string)=>{setToast(m);window.setTimeout(()=>setToast(''),2400)};const navTo=(p:string)=>{setPage(p);setOpen(false);setSelected(null);const group=nav.find(g=>g.items.some(([id])=>id===p));if(group)setOpenNavGroup(group.title);window.scrollTo({top:0,behavior:'smooth'})};const changeTheme=(v:boolean)=>{setDark(v);localStorage.setItem('novisoft-theme',v?'dark':'light')};const logout=()=>{sessionStorage.removeItem('novisoft-auth');sessionStorage.removeItem('novisoft-token');sessionStorage.removeItem('novisoft-user');setAuthenticated(false);setPage('dashboard')};const addTicket=async(x:Omit<TicketItem,'id'|'updated'|'sla'>)=>{try{const created=await apiFetch('/tickets',{method:'POST',body:JSON.stringify({...x,sla:'04:00'})});const row={id:created.id,title:created.title,status:created.status,priority:created.priority,requester:created.requester,assignee:created.assignee,category:created.category,updated:'همین الان',sla:created.sla,department:created.department,service:created.service,description:created.description};setTickets(prev=>[row,...prev]);notify(`تیکت #${created.id} با موفقیت ثبت شد`);navTo('tickets')}catch(err:any){notify(err?.message||'ثبت تیکت در سرور انجام نشد')}};const renderPage=()=>{if(page==='dashboard')return <div className="dashboardEnter"><Dashboard tickets={tickets} onOpen={setSelected} onNavigate={navTo}/></div>;if(page==='tickets')return <><PageHeader title="تیکت‌ها" sub="مدیریت، جستجو، فیلتر و پیگیری تمام تیکت‌های سازمان" action="ثبت تیکت" onAction={()=>navTo('new')}/><Panel title="فهرست تیکت‌ها" sub={`${filtered.length} مورد یافت شد`}><FilterBar {...{q,setQ,status,setStatus,priority,setPriority,department,setDepartment,category,setCategory}}/><TicketTable rows={filtered} onOpen={setSelected}/></Panel></>;if(page==='myTickets')return <><PageHeader title="تیکت‌های من" sub="تیکت‌هایی که به شما یا تیم شما تخصیص داده شده است" action="ثبت تیکت" onAction={()=>navTo('new')}/><Panel title="تیکت‌های من" sub={`${filtered.filter(t=>t.assignee==='علی رضایی').length} تیکت`}><FilterBar {...{q,setQ,status,setStatus,priority,setPriority,department,setDepartment,category,setCategory}}/><TicketTable rows={filtered.filter(t=>t.assignee==='علی رضایی')} onOpen={setSelected}/></Panel></>;if(page==='new')return <NewTicket onCancel={()=>navTo('dashboard')} onCreate={addTicket}/>;switch(page){case'incidents':return <IncidentsPage notify={notify}/>;case'requests':return <RequestsPage notify={notify}/>;case'problems':return <ProblemsPage/>;case'changes':return <ChangesPage notify={notify}/>;case'services':return <ServicesPage notify={notify}/>;case'sla':return <SlaPage notify={notify}/>;case'approvals':return <ApprovalsPage/>;case'knowledge':return <KnowledgePage notify={notify}/>;case'assets':return <AssetsPage/>;case'users':return <UsersPage notify={notify}/>;case'reports':return <ReportsPage notify={notify}/>;case'notifications':return <NotificationsPage notify={notify}/>;case'settings':return <SettingsPage notify={notify} dark={dark} setDark={changeTheme}/>;default:if(enterpriseModules[page])return <EnterprisePage id={page} notify={notify}/>;return <Dashboard tickets={tickets} onOpen={setSelected} onNavigate={navTo}/>} };if(!authenticated)return <LoginPage onLogin={()=>setAuthenticated(true)}/>;return <div className={'app '+(dark?'theme-dark':'')}><style>{accordionSidebarStyles}</style><aside className={'sidebar '+(open?'mobileOpen':'')}><div className="brand"><img src={`${import.meta.env.BASE_URL}novisoft-logo.png`}/><div><b>نووی سافت</b><small>سیستم مدیریت خدمات فناوری اطلاعات</small></div></div><div className="workspace"><Building2 size={17}/><span>سازمان دوماس</span><ChevronDown size={15}/></div><nav className="accordionNav">{nav.map(g=>{const isOpen=openNavGroup===g.title;const hasActivePage=g.items.some(([id])=>page===id);return <div className={'navGroup '+(isOpen?'expanded':'')} key={g.title}><button type="button" className={'navTitle '+(hasActivePage?'hasActive':'')} onClick={()=>setOpenNavGroup(isOpen?'':g.title)}><span>{g.title}</span><ChevronDown size={16} className={isOpen?'navChevron rotated':'navChevron'}/></button><div className={'navItems '+(isOpen?'show':'')}>{g.items.map(([id,label,Icon])=>{const I=Icon as any;return <button type="button" key={String(id)} className={page===id?'active':''} onClick={()=>navTo(id as string)}><I size={17}/><span>{label as string}</span>{id==='tickets'&&<em>12</em>}</button>})}</div></div>})}</nav><div className="profile"><div className="avatar">م</div><div><b>محمدرضا</b><small>مدیر سیستم</small></div><button className="logoutBtn" onClick={logout} title="خروج"><LogOut size={17}/></button></div></aside><main><header><button className="menuBtn" onClick={()=>setOpen(!open)}><Menu/></button><div className="search"><Search size={18}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="جستجو در تیکت‌ها، کاربران و خدمات..."/></div><div className="headerRight"><button className="newBtn" onClick={()=>navTo('new')}><Plus size={18}/>ثبت تیکت جدید</button><button className="iconBtn" onClick={()=>navTo('notifications')}><Bell size={19}/><i>3</i></button></div></header><section className="content">{renderPage()}</section></main>{selected&&<Drawer ticket={selected} close={()=>setSelected(null)} notify={notify}/>} {toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}</div>}</div>}
function Drawer({ticket,close,notify}:{ticket:TicketItem;close:()=>void;notify:(s:string)=>void}){return <div className="drawerBack" onClick={close}><aside className="drawer" onClick={e=>e.stopPropagation()}><div className="drawerHead"><div><span>تیکت #{ticket.id}</span><h2>{ticket.title}</h2></div><button onClick={close}><X/></button></div><div className="drawerTags"><span className={'pill '+priorityClass(ticket.priority)}>{ticket.priority}</span><span className={'pill '+statusClass(ticket.status)}>{ticket.status}</span><span className="sla">SLA: {ticket.sla}</span></div><div className="meta"><div><small>درخواست‌کننده</small><b>{ticket.requester}</b></div><div><small>کارشناس</small><b>{ticket.assignee}</b></div><div><small>خدمت</small><b>{ticket.service||'—'}</b></div><div><small>واحد</small><b>{ticket.department}</b></div></div><div className="drawerInfo"><div><span>شرح</span><p>{ticket.description||'سلام، این مشکل از ابتدای شیفت ایجاد شده و دسترسی کاربران به سرویس با اختلال مواجه است.'}</p></div></div><div className="conversation"><div className="msg user"><b>{ticket.requester}</b><small>امروز، 10:12</small><p>مشکل از ابتدای شیفت ایجاد شده و دسترسی کاربران به سرویس با اختلال مواجه است.</p></div><div className="msg agent"><b>{ticket.assignee}</b><small>امروز، 10:24</small><p>در حال بررسی موضوع هستم. نتیجه بررسی را در همین تیکت اعلام می‌کنم.</p></div></div><div className="reply"><textarea placeholder="پاسخ خود را بنویسید..."/><button className="newBtn" onClick={()=>notify('پاسخ تیکت ثبت شد')}><MessageSquare size={16}/>ارسال پاسخ</button></div></aside></div>}

export default App




